import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createPublicKey, generateKeyPairSync, verify } from "node:crypto";
import {
  access,
  mkdir,
  readFile,
  readdir,
  symlink,
  writeFile,
} from "node:fs/promises";
import path from "node:path";
import { digest } from "./fixtures/native-release.mjs";
import {
  inspectHandoff,
  main,
  signCatalogProposal,
} from "../scripts/sign-catalog-proposal.mjs";
import { verifyCatalog } from "../../scripts/catalog-lib.mjs";

const readJson = async (file) => JSON.parse(await readFile(file, "utf8"));
const absent = async (file) => assert.rejects(access(file), { code: "ENOENT" });
import { signingFixture } from "./fixtures/catalog-signing.mjs";

test("signs the exact reviewed bytes with the independently selected Ed25519 key", async (t) => {
  const f = await signingFixture(t);
  const proposed = path.join(f.signing.directory, "catalog.proposed.json");
  // Whitespace/order must not be regenerated by a signer.
  const original = Buffer.from(
    "\n" + JSON.stringify(await readJson(proposed)) + "\n\n",
  );
  await writeFile(proposed, original);
  await f.repin();
  const inputHashes = new Map();
  for (const name of await readdir(f.signing.directory))
    inputHashes.set(
      name,
      digest(await readFile(path.join(f.signing.directory, name))),
    );
  const result = await signCatalogProposal(f.signing);
  assert.equal(f.keyReads(), 1);
  assert.deepEqual(
    await readFile(path.join(f.signing.output, "catalog.json")),
    original,
  );
  const sig = Buffer.from(
    (await readFile(path.join(f.signing.output, "catalog.sig"), "utf8")).trim(),
    "base64",
  );
  assert.ok(verify(null, original, createPublicKey(f.key), sig));
  assert.equal(
    (await verifyCatalog(f.signing.output, true)).artifacts.length,
    44,
  );
  assert.equal(result.catalogSha256, digest(original));
  assert.equal(result.scope, "catalog-signature-only");
  assert.equal(result.productionApproved, false);
  for (const entry of result.files) {
    const bytes = await readFile(path.join(f.signing.output, entry.name));
    assert.equal(digest(bytes), entry.sha256);
    assert.equal(bytes.length, entry.size);
  }
  const provenance = await readJson(
    path.join(f.signing.output, "provenance.json"),
  );
  assert.equal(provenance.developmentKey, false);
  assert.equal(provenance.handoffSha256, f.signing.handoffSha256);
  assert.equal((await readdir(f.signing.output)).length, 5);
  for (const [name, sha256] of inputHashes)
    assert.equal(
      digest(await readFile(path.join(f.signing.directory, name))),
      sha256,
    );
});

test("review-only handoffs fail before private-key access or output creation", async (t) => {
  const f = await signingFixture(t, false);
  await assert.rejects(
    signCatalogProposal(f.signing),
    /complete public-byte verification/,
  );
  assert.equal(f.keyReads(), 0);
  await absent(f.signing.output);
});

test("check-only validates all inputs and destination without reading a private key or writing output", async (t) => {
  const f = await signingFixture(t);
  const result = await signCatalogProposal({
    ...f.signing,
    checkOnly: true,
    loadPrivateKey: () => {
      throw new Error("must not open a key");
    },
  });
  assert.equal(result.privateKeyAccessed, false);
  assert.equal(result.catalogSigned, false);
  assert.equal(result.productionApproved, false);
  await absent(f.signing.output);
});

test("requires separate retained pins and forbids the known development signing identity", async (t) => {
  const f = await signingFixture(t);
  for (const change of [
    { handoffSha256: undefined },
    { handoffSha256: "0".repeat(64) },
    { basePublicKeySha256: undefined },
    { basePublicKeySha256: "0".repeat(64) },
    { publicKeySha256: undefined },
    {
      publicKeySha256:
        "203a1d0ff09c35d787e568a4cc4e746437454cf075a179960cfbb378597820d0",
    },
  ])
    await assert.rejects(
      signCatalogProposal({ ...f.signing, ...change }),
      /retained|hash mismatch|trust root|production public-key/,
    );
  assert.equal(f.keyReads(), 0);
  await absent(f.signing.output);
});

test("replacing handoff and all file checksums cannot replace a separately retained review hash", async (t) => {
  const f = await signingFixture(t);
  const held = f.signing.handoffSha256;
  await f.change(
    "catalog.proposed.json",
    (value) => (value.generatedAt = "2026-01-01T00:00:00Z"),
  );
  await f.repin();
  await assert.rejects(
    signCatalogProposal({ ...f.signing, handoffSha256: held }),
    /Retained handoff hash mismatch/,
  );
  assert.equal(f.keyReads(), 0);
  await absent(f.signing.output);
});

test("changed control bytes, extra files, unsafe inventory names and duplicates fail before opening a key", async (t) => {
  for (const mode of ["corrupt", "extra", "traversal", "duplicate"]) {
    const f = await signingFixture(t);
    if (mode === "corrupt")
      await writeFile(
        path.join(f.signing.directory, "source-inventory.json"),
        "[]",
      );
    if (mode === "extra")
      await writeFile(path.join(f.signing.directory, "unexpected.json"), "{}");
    if (mode === "traversal")
      await f.repin((value) => (value.files[0].name = "../outside"));
    if (mode === "duplicate")
      await f.repin((value) => (value.files[0] = value.files[1]));
    await assert.rejects(
      signCatalogProposal(f.signing),
      /checksum\/size mismatch|unrecorded|file inventory/,
    );
    assert.equal(f.keyReads(), 0);
    await absent(f.signing.output);
  }
});

test("a signature is checked again even if a new review checksum records its altered bytes", async (t) => {
  const f = await signingFixture(t);
  await writeFile(
    path.join(f.signing.directory, "base-catalog.sig"),
    Buffer.alloc(64).toString("base64"),
  );
  await f.repin();
  await assert.rejects(
    signCatalogProposal(f.signing),
    /Invalid base catalog signature/,
  );
  assert.equal(f.keyReads(), 0);
});

test("the proposed catalog must exactly preserve the signed base and native records", async (t) => {
  const f = await signingFixture(t);
  await f.change(
    "catalog.proposed.json",
    (value) => (value.artifacts[0].url = "https://example.test/replaced.tgz"),
  );
  await f.repin();
  await assert.rejects(
    signCatalogProposal(f.signing),
    /immutable base\/native merge/,
  );
  assert.equal(f.keyReads(), 0);
  await absent(f.signing.output);
});

test("public verification must cover the exact manifest, every file and the total byte count", async (t) => {
  for (const mode of [
    "manifest-pin",
    "files",
    "bytes",
    "host",
    "producer",
    "control-pin",
    "checksum-inventory",
  ]) {
    const f = await signingFixture(t);
    if (mode === "manifest-pin")
      await f.repin((value) => (value.manifestSha256 = "0".repeat(64)));
    else {
      await f.change("candidate-verification.json", (value) => {
        if (mode === "files") value.files.pop();
        if (mode === "bytes") value.hostedVerification.bytes--;
        if (mode === "host")
          value.hostedVerification.baseUrl = "https://example.test/native";
        if (mode === "producer") value.producers[0].run = "99999";
        if (mode === "control-pin")
          value.sourceInventorySha256 = "0".repeat(64);
        if (mode === "checksum-inventory") {
          value.files.find((item) => item.name === "SHA256SUMS.txt").name =
            "unrecorded.txt";
          delete value.checksumFileSha256;
        }
      });
      await f.repin((value) => {
        if (mode === "bytes") value.hostedVerification.bytes--;
        if (mode === "host")
          value.hostedVerification.baseUrl = "https://example.test/native";
      });
    }
    await assert.rejects(
      signCatalogProposal(f.signing),
      /identity mismatch|verification inventory|every candidate byte|producer identities|inventory pin mismatch/,
    );
    assert.equal(f.keyReads(), 0);
    await absent(f.signing.output);
  }
});

test("a wrong private key or algorithm cannot produce any signed output", async (t) => {
  for (const key of [
    generateKeyPairSync("ed25519").privateKey,
    generateKeyPairSync("ec", { namedCurve: "prime256v1" }).privateKey,
    generateKeyPairSync("ed25519").publicKey,
  ]) {
    const f = await signingFixture(t);
    await assert.rejects(
      signCatalogProposal({ ...f.signing, loadPrivateKey: () => key }),
      /does not match|Ed25519 private key/,
    );
    await absent(f.signing.output);
  }
});

test("output cannot replace prior files, overlap a handoff or write into shipping resources", async (t) => {
  const f = await signingFixture(t);
  await mkdir(f.signing.output);
  await writeFile(path.join(f.signing.output, "keep.txt"), "untouched");
  for (const output of [
    f.signing.output,
    path.join(f.signing.directory, "child"),
    f.root,
    path.resolve(import.meta.dirname, "../../runtime-catalog/signing-output"),
  ])
    await assert.rejects(
      signCatalogProposal({ ...f.signing, output }),
      /already exists|separate from/,
    );
  assert.equal(f.keyReads(), 0);
  assert.equal(
    await readFile(path.join(f.signing.output, "keep.txt"), "utf8"),
    "untouched",
  );
  const link = path.join(f.root, "linked-handoff");
  await symlink(
    f.signing.directory,
    link,
    process.platform === "win32" ? "junction" : "dir",
  );
  await assert.rejects(
    inspectHandoff({ ...f.signing, directory: link }),
    /real directory/,
  );
});

test("a destination created after validation is never overwritten", async (t) => {
  const f = await signingFixture(t);
  await assert.rejects(
    signCatalogProposal({
      ...f.signing,
      loadPrivateKey: async () => {
        await mkdir(f.signing.output);
        await writeFile(path.join(f.signing.output, "keep.txt"), "new owner");
        return f.key;
      },
    }),
    { code: "EEXIST" },
  );
  assert.equal(
    await readFile(path.join(f.signing.output, "keep.txt"), "utf8"),
    "new owner",
  );
  await absent(path.join(f.signing.output, "SIGNING_RECEIPT.json"));
});

test("late input changes cannot change the captured, reviewed bytes being signed", async (t) => {
  const f = await signingFixture(t);
  const file = path.join(f.signing.directory, "catalog.proposed.json"),
    original = await readFile(file);
  const result = await signCatalogProposal({
    ...f.signing,
    loadPrivateKey: async () => {
      await writeFile(file, "changed after validation");
      return f.key;
    },
  });
  assert.deepEqual(
    await readFile(path.join(f.signing.output, "catalog.json")),
    original,
  );
  assert.equal(result.catalogSha256, digest(original));
});

test("CLI requires all pins and rejects implicit development or overwrite modes", async (t) => {
  const f = await signingFixture(t);
  const args = Object.entries({
    directory: f.signing.directory,
    "handoff-sha256": f.signing.handoffSha256,
    "base-public-key-sha256": f.signing.basePublicKeySha256,
    "public-key-sha256": f.signing.publicKeySha256,
    output: f.signing.output,
  }).map(([name, value]) => `--${name}=${value}`);
  await assert.rejects(
    main(args.filter((value) => !value.startsWith("--handoff-sha256="))),
    /Missing required/,
  );
  for (const option of ["--dev", "--overwrite", args[0]])
    await assert.rejects(main([...args, option]), /Unknown or duplicate/);
  const result = await main([...args, "--check-only"], {
    loadPrivateKey: () => {
      throw new Error("must not read key");
    },
  });
  assert.equal(result.privateKeyAccessed, false);
  await absent(f.signing.output);
});

test("real CLI handles missing/malformed keys without leaking them and signs with an ephemeral test environment", async (t) => {
  for (const mode of ["missing", "malformed", "valid"]) {
    const f = await signingFixture(t);
    const args = Object.entries({
      directory: f.signing.directory,
      "handoff-sha256": f.signing.handoffSha256,
      "base-public-key-sha256": f.signing.basePublicKeySha256,
      "public-key-sha256": f.signing.publicKeySha256,
      output: f.signing.output,
    }).map(([name, value]) => `--${name}=${value}`);
    // An allowlisted child environment never inherits the operator's secrets.
    const env = {
      SystemRoot: process.env.SystemRoot,
      PATH: path.dirname(process.execPath),
    };
    const sentinel = "INVALID_TEST_KEY_MUST_NEVER_APPEAR_IN_OUTPUT";
    if (mode === "malformed") env.STACKCABIN_CATALOG_PRIVATE_KEY = sentinel;
    if (mode === "valid")
      env.STACKCABIN_CATALOG_PRIVATE_KEY = f.key
        .export({ type: "pkcs8", format: "pem" })
        .replaceAll("\n", "\\n");
    const child = spawnSync(
      process.execPath,
      [
        path.resolve(
          import.meta.dirname,
          "../scripts/sign-catalog-proposal.mjs",
        ),
        ...args,
      ],
      { env, encoding: "utf8", timeout: 30_000 },
    );
    assert.equal(child.error, undefined);
    assert.equal(child.signal, null);
    assert.equal(child.status, mode === "valid" ? 0 : 1);
    assert.ok(!`${child.stdout}${child.stderr}`.includes(sentinel));
    assert.ok(!`${child.stdout}${child.stderr}`.includes("BEGIN PRIVATE KEY"));
    if (mode === "valid") {
      assert.equal(JSON.parse(child.stdout).catalogSigned, true);
      assert.equal(
        (await verifyCatalog(f.signing.output, true)).artifacts.length,
        44,
      );
    } else {
      assert.match(
        child.stderr,
        mode === "missing"
          ? /Set STACKCABIN_CATALOG_PRIVATE_KEY/
          : /Invalid private signing key/,
      );
      await absent(f.signing.output);
    }
  }
});
